/** Starter FAQ (also seeded into the database). */
export const SEED_FAQ: { q: T2; a: T2; section?: string }[] = [
  { q: { en: "Where can I read how the whole system works?", ru: "Где прочитать, как устроена вся система?" }, a: { en: "Learning Center → **How it works**. Sixteen chapters: what Workspace is, the first day, records, access and US-persons-only data, approvals and status gates, smart upload and email intake, the AI assistant, automation, agents, emails and timing, reports, marketing, security and backups, owner settings, phone use and troubleshooting.", ru: "Learning Center → **«Как всё устроено»**. Шестнадцать глав: что такое Workspace, первый день, записи, доступ и данные «только для US persons», согласования и запреты статусов, умная загрузка и приём почты, ИИ-ассистент, автоматизация, агенты, письма и расписание, отчёты, маркетинг, безопасность и бэкапы, настройки владельца, телефон и решение проблем." } },
  { q: { en: "What is the difference between Suggest and Auto?", ru: "Чем отличается «Предлагает» от «Сам»?" }, a: { en: "**Suggest** prepares the change and waits in *Waiting for approval* until an owner or admin approves it. **Auto** makes the change at once and writes it to the agent log. In both modes team notifications go out, and emails to outside addresses always wait for a person.", ru: "**«Предлагает»** готовит изменение и ждёт в «Ждут одобрения», пока владелец или администратор не одобрит. **«Сам»** делает изменение сразу и записывает его в журнал агентов. В обоих режимах уведомления команде уходят, а письма на внешние адреса всегда ждут человека." } },
  { q: { en: "Can an agent send an email to a client by itself?", ru: "Может ли агент сам отправить письмо клиенту?" }, a: { en: "No. An agent can only draft it. The draft waits in the approval queue; you can read and edit it, then approve — only then it is sent. This holds in every mode.", ru: "Нет. Агент может только подготовить черновик. Черновик ждёт в очереди одобрения; его можно прочитать и отредактировать, затем одобрить — только тогда оно уйдёт. Так в любом режиме." } },
  { q: { en: "When do agents and emails run?", ru: "Когда работают агенты и приходят письма?" }, a: { en: "Rules on save — within seconds. Agents and monitoring — every working day at 10:00 UTC. Morning digest — 11:00 UTC. Email intake — every 15 minutes. Monday brief and automatic backup — Monday. Department reports — on the 1st of the month.", ru: "Правила при сохранении — через секунды. Агенты и мониторинг — каждый рабочий день в 10:00 UTC. Утренняя сводка — 11:00 UTC. Приём почты — каждые 15 минут. Сводка по понедельникам и автоматический бэкап — в понедельник. Отчёты департаментов — 1-го числа." } },
  { q: { en: "Does the AI see everything in Workspace?", ru: "Видит ли ИИ всё в Workspace?" }, a: { en: "No. The assistant reads only what your role may read, and US-persons-only content only for confirmed US persons. Commands run with your own rights. AI never deletes, signs, pays or emails outside the company.", ru: "Нет. Ассистент читает только то, что может читать ваша роль, а данные «только для US persons» — только для подтверждённых US persons. Команды выполняются с вашими правами. ИИ никогда не удаляет, не подписывает, не платит и не пишет за пределы компании." } },
  { q: { en: "Does email intake change or delete letters in the inbox?", ru: "Меняет или удаляет ли приём почты письма в ящике?" }, a: { en: "No. The inbox is read-only for Workspace: nothing is deleted, moved, marked or answered. Newsletters, auto-replies and spam are skipped; real letters become records (in Suggest mode — after your approval).", ru: "Нет. Для Workspace ящик только на чтение: ничего не удаляется, не перемещается, не помечается и не отвечается. Рассылки, автоответы и спам пропускаются; настоящие письма становятся записями (в режиме «Предлагает» — после вашего одобрения)." } },
  { q: { en: "Will restoring a backup overwrite current data?", ru: "Перезапишет ли восстановление бэкапа текущие данные?" }, a: { en: "No. Restore puts back only records and comments that no longer exist. Current records stay as they are.", ru: "Нет. Восстановление возвращает только записи и комментарии, которых больше нет. Текущие записи остаются как есть." } },
  { q: { en: "Why are my report numbers different from what I expect?", ru: "Почему цифры в отчёте не такие, как я жду?" }, a: { en: "Reports count only records you can see and by their current status. A wrong status or a missing amount changes the result. Open the number to see the records behind it; the Data quality agent lists records with missing fields.", ru: "Отчёты считают только видимые вам записи и по их текущему статусу. Неверный статус или пустая сумма меняют результат. Нажмите на цифру, чтобы увидеть записи за ней; агент «Качество данных» показывает записи с пустыми полями." } },
  { q: { en: "Where are service keys and passwords entered?", ru: "Где вводятся сервисные ключи и пароли?" }, a: { en: "Never in Workspace. The owner stores them only in the hosting settings. System → Health shows only whether each key is set.", ru: "Никогда не в Workspace. Владелец хранит их только в настройках хостинга. «Система» → «Состояние» показывает только, задан ли каждый ключ." } },
  { q: { en: "Can I dictate a question or a command?", ru: "Можно ли надиктовать вопрос или команду?" }, a: { en: "Yes. In Ask AI press the microphone next to Send and speak in the interface language; the text appears in the box. Check it and press Send — in Do mode you will still see the plan and confirm it. Works in Chrome, Edge and Safari; the browser asks for microphone access the first time.", ru: "Да. В «Спросить ИИ» нажмите микрофон рядом с «Отправить» и говорите на языке интерфейса — текст появится в поле. Проверьте его и нажмите «Отправить»; в режиме «Сделать» вы всё равно увидите план и подтвердите его. Работает в Chrome, Edge и Safari; в первый раз браузер спросит доступ к микрофону." } },
  { q: { en: "Can I tell Workspace what to do in my own words?", ru: "Можно ли сказать Workspace, что сделать, своими словами?" }, a: { en: "Yes. Open Ask AI, switch to Do and write the command, for example “move the Aurora deal to Negotiation and create a task for Ivan for Friday to send the contract”. AI shows the plan; press “Yes, do it” and the changes are made with your rights. Nothing changes until you confirm, and nothing is ever deleted.", ru: "Да. Откройте «Спросить ИИ», переключите на «Сделать» и напишите команду, например «переведи сделку Aurora в Negotiation и создай задачу Ивану на пятницу отправить договор». ИИ покажет план; нажмите «Да, выполнить» — изменения внесутся с вашими правами. Пока вы не подтвердили, ничего не меняется, и ничего никогда не удаляется." } },
  { q: { en: "Does AI write and send letters to clients?", ru: "Пишет ли ИИ письма клиентам и отправляет ли их?" }, a: { en: "It writes drafts; a person sends them. Replies to new inquiries, follow-ups on stalled deals and notes on expiring proposals appear in System → Automation → Waiting for approval. Open “Read and edit the letter”, correct it if needed and press Approve — the letter goes from info@agron1.com. Drafts use only approved Brand center texts and never include prices or technical data.", ru: "Пишет черновики, а отправляет человек. Ответы на новые запросы, напоминания по стоящим сделкам и письма по истекающим КП появляются в «Система» → «Автоматизация» → «Ждут одобрения». Откройте «Прочитать и поправить письмо», исправьте при необходимости и нажмите «Одобрить» — письмо уйдёт с info@agron1.com. Черновики используют только одобренные тексты Бренд-центра и никогда не содержат цен или технических данных." } },
  { q: { en: "How do I put a document into Workspace by email?", ru: "Как внести документ в Workspace по почте?" }, a: { en: "Forward the letter with its attachments to info@agron1.com. The Email intake agent reads it, AI chooses the section and fills the fields, and the record appears with the files — right away in Auto mode, or after one-click approval in System → Automation in Suggest mode.", ru: "Перешлите письмо с вложениями на info@agron1.com. Агент «Входящая почта» прочитает его, ИИ выберет раздел и заполнит поля, и запись появится с файлами — сразу в режиме «Сам» или после одобрения одним кликом в «Система» → «Автоматизация» в режиме «Предлагает»." } },
  { q: { en: "Who makes sure access is reviewed and removed on time?", ru: "Кто следит, чтобы доступы пересматривались и отзывались вовремя?" }, a: { en: "The Security agent. Each quarter it prepares a “Quarterly access review” record due in 7 days; do the review in Security → Overview → Access review and mark the record Done. When someone leaves, the HR agent creates “Revoke access — name” due the same day, and if it is not Done the Security agent tells leaders every day.", ru: "Агент безопасности. Каждый квартал он готовит запись «Quarterly access review» со сроком 7 дней; сделайте пересмотр в «Безопасность» → «Обзор» → «Пересмотр доступов» и отметьте запись Done. Когда сотрудник уходит, агент HR создаёт «Revoke access — имя» со сроком в тот же день, и если она не Done, агент безопасности каждый день сообщает руководству." } },
  { q: { en: "What happens when a test fails?", ru: "Что происходит, когда тест провален?" }, a: { en: "Mark the test Failed in Technical → Testing and write the result. The Technical agent prepares a High-priority bug “Fix failed test — name” in Software with the test result in the notes and tells engineering. Only one bug per test is created.", ru: "Отметьте тест Failed в «Технический» → «Испытания» и запишите результат. Технический агент готовит баг с высоким приоритетом «Fix failed test — название» в «ПО» с результатом теста в заметках и сообщает инженерам. На один тест создаётся только один баг." } },
  { q: { en: "Can a post go out without the release check?", ru: "Может ли пост выйти без проверки к публикации?" }, a: { en: "No. A post, article, interview or video cannot be moved to Approved, Scheduled or Published until the check is “Passed (AI check)” or “Cleared by legal”. The Marketing agent also reminds the author about anything at Review without a check and sends “Legal review needed” items to Legal.", ru: "Нет. Пост, статью, интервью или видео нельзя перевести в Approved, Scheduled или Published, пока проверка не «Passed (AI check)» или «Cleared by legal». Агент маркетинга ещё и напоминает автору о материалах на Review без проверки и отправляет юристам всё с «Legal review needed»." } },
  { q: { en: "Which agents work in Workspace?", ru: "Какие агенты работают в Workspace?" }, a: { en: "Thirteen, every working day at 10:00 UTC: Rules, Deadlines, Compliance, Data quality and the Monday brief for the whole company, plus one agent each for Finance, Sales, Operations, HR, Legal, Marketing, Technical and Security. Each department overview shows what its agent sees now. Modes and runs: Administration → System → Automation.", ru: "Тринадцать, каждый рабочий день в 10:00 UTC: Правила, Сроки, Комплаенс, Качество данных и Сводка по понедельникам для всей компании, плюс по агенту для Финансов, Продаж, Операций, HR, Юристов, Маркетинга, Технического департамента и Безопасности. Обзор каждого департамента показывает, что его агент видит сейчас. Режимы и запуск: «Администрирование» → «Система» → «Автоматизация»." } },
  { q: { en: "How are recurring legal obligations kept?", ru: "Как ведутся повторяющиеся юридические обязательства?" }, a: { en: "Set Frequency (Monthly, Quarterly or Annual) and the due date in Legal → Obligations. When you mark it Done, the Legal agent creates the next one with the same details and the next due date, and warns 60, 30 and 7 days before it.", ru: "Укажите «Периодичность» (Monthly, Quarterly или Annual) и срок в «Юридический» → «Обязательства». Когда отметите Done, агент юристов создаст следующее с теми же данными и следующей датой и предупредит за 60, 30 и 7 дней." } },
  { q: { en: "What happens when an employee leaves?", ru: "Что происходит, когда сотрудник уходит?" }, a: { en: "Mark the person Left in HR → Team. The HR agent prepares an offboarding checklist and a Security → Access record “Revoke access — name” due the same day, lists company items still issued to the person, and tells HR and Security. Approve the proposals in System → Automation (or let the agent act on its own in Auto mode).", ru: "Отметьте человека Left в «HR» → «Команда». Агент HR готовит чек-лист увольнения и запись в «Безопасность» → «Доступы» «Revoke access — имя» со сроком в тот же день, перечисляет не сданное имущество и сообщает HR и Безопасности. Одобрите предложения в «Система» → «Автоматизация» (или в режиме «Сам» агент сделает это сам)." } },
  { q: { en: "What happens automatically after a container is delivered?", ru: "Что происходит автоматически после доставки контейнера?" }, a: { en: "When the shipment is marked Delivered, the Operations agent prepares an installation record for the build. When the installation is marked Commissioned, it moves the build to Installed and adds the unit to the fleet with a 12-month warranty and the first service in 6 months; the Rules agent then creates the client acceptance task. Near the service date a service ticket is prepared.", ru: "Когда груз отмечен Delivered, агент операций готовит запись монтажа для сборки. Когда монтаж отмечен Commissioned, он переводит сборку в Installed и добавляет систему в парк с гарантией 12 месяцев и первым сервисом через 6 месяцев; затем агент «Правила» создаёт задачу на приёмку клиентом. Ближе к дате сервиса готовится сервисная заявка." } },
  { q: { en: "Who reminds us about stalled deals?", ru: "Кто напоминает о сделках без движения?" }, a: { en: "The Sales agent. When a deal has had no change for the number of days set in System → Settings (14 by default), it prepares a High-priority follow-up task for the deal owner, due in two days, and tells the owner. One task per deal; when the deal moves, the reminders stop.", ru: "Агент продаж. Когда в сделке нет изменений столько дней, сколько задано в «Система» → «Настройки» (по умолчанию 14), он готовит для ответственного задачу на контакт с высоким приоритетом и сроком два дня и сообщает ему. Одна задача на сделку; когда сделка сдвинулась, напоминания прекращаются." } },
  { q: { en: "Will Workspace remind clients to pay by itself?", ru: "Будет ли Workspace сам напоминать клиентам об оплате?" }, a: { en: "It prepares the reminder, a person sends it. When a receivable invoice is 7 or more days late, the Finance agent writes a polite reminder to the email on the client card (found through the linked deal or the counterparty name) and puts it under System → Automation → Waiting for approval. Approve, and it goes from info@agron1.com. Repeats every 14 days while unpaid; after 30 days leaders are told too.", ru: "Готовит напоминание, а отправляет человек. Когда входящий счёт просрочен на 7 и более дней, агент финансов пишет вежливое напоминание на адрес из карточки клиента (находит через связанную сделку или имя контрагента) и кладёт его в «Система» → «Автоматизация» → «Ждут одобрения». Одобрите — и письмо уйдёт с info@agron1.com. Повторяется каждые 14 дней, пока счёт не оплачен; после 30 дней сообщается и руководству." } },
  { q: { en: "How do I let Workspace do routine work by itself?", ru: "Как поручить Workspace рутину, чтобы она делалась сама?" }, a: { en: "Administration → System → Automation. Five agents run every working day: Rules, Deadlines, Compliance, Data quality and the Monday brief. Start in Suggest mode: agents prepare changes and you approve them in one click under Waiting for approval. When a rule or agent has proved itself for a couple of weeks, switch it to Auto.", ru: "«Администрирование» → «Система» → «Автоматизация». Пять агентов работают каждый рабочий день: Правила, Сроки, Комплаенс, Качество данных и Сводка по понедельникам. Начните с режима «Предлагает»: агенты готовят изменения, а вы одобряете их одним кликом в блоке «Ждут одобрения». Когда правило или агент пару недель работает без ошибок, переключите его в «Сам»." } },
  { q: { en: "Can an agent send an email to a client or pay something by itself?", ru: "Может ли агент сам отправить письмо клиенту или что-то оплатить?" }, a: { en: "No. Emails to outside addresses always wait for a person's approval, and agents never pay, sign or publish. Only team notifications inside the company go out automatically. Records marked US persons only are announced only to US persons, and their proposals can be approved only by a US person.", ru: "Нет. Письма на внешние адреса всегда ждут одобрения человека, а платить, подписывать и публиковать агенты не могут. Автоматически уходят только уведомления команде внутри компании. О записях «только для US persons» сообщается только US persons, и одобрить такие предложения может только US person." } },
  { q: { en: "How do I create my own rule?", ru: "Как создать своё правило?" }, a: { en: "System → Automation → Rules → New rule. Choose when (a status changes, a record is added or a date comes), the section, optional conditions, then actions: notify people, create a linked record, change a field or email an outside address. Use {title}, {client} and other fields in the text. Save and keep it in Suggest mode first.", ru: "«Система» → «Автоматизация» → «Правила» → «Новое правило». Выберите, когда (меняется статус, добавлена запись или наступает дата), раздел, условия при необходимости, затем действия: уведомить людей, создать связанную запись, изменить поле или написать на внешний адрес. В тексте используйте {title}, {client} и другие поля. Сохраните и сначала держите в режиме «Предлагает»." } },
  { q: { en: "What happens automatically when a deal is won?", ru: "Что происходит автоматически, когда сделка выиграна?" }, a: { en: "With the ready-made rules: a container build (linked to the deal) and a draft receivable invoice with the client, amount and currency are prepared, and Operations and Finance are notified. Earlier stages also help: at Proposal a sanctions screening is prepared, at Negotiation a contract draft record.", ru: "По готовым правилам: готовятся сборка контейнера (связанная со сделкой) и черновик входящего счёта с клиентом, суммой и валютой, Операции и Финансы получают уведомление. Помогают и ранние этапы: на Proposal готовится санкционная проверка, на Negotiation — запись черновика договора." } },
  { q: { en: "What is the Monday brief?", ru: "Что такое сводка по понедельникам?" }, a: { en: "Every Monday the CEO gets one email: open pipeline, deals won, new leads, receivables and overdue invoices, overdue items by department, builds, support tickets, screenings, approvals and proposals waiting, monitoring and data quality — plus five AI conclusions if the AI budget allows. Recipients are set in System → Settings. US-persons-only records are not included.", ru: "Каждый понедельник CEO получает одно письмо: открытая воронка, выигранные сделки, новые лиды, дебиторка и просроченные счета, просрочки по департаментам, сборки, заявки в поддержку, проверки, ожидающие согласования и предложения агентов, мониторинг и качество данных — плюс пять выводов ИИ, если позволяет бюджет. Получателей задают в «Система» → «Настройки». Записи «только для US persons» не включаются." } },
  { q: { en: "How do I see everything automation changed?", ru: "Как увидеть всё, что изменила автоматика?" }, a: { en: "System → Data quality & audit → Audit trail → Automation only. Each line shows the record, what was done and why; the Agent log on the Automation tab adds runs and errors. Download CSV for a full copy.", ru: "«Система» → «Качество данных и аудит» → «Журнал изменений» → «Только автоматизация». В каждой строке — запись, что сделано и почему; «Журнал агентов» на вкладке «Автоматизация» добавляет запуски и ошибки. Для полной копии — выгрузка CSV." } },
  { q: { en: "How do I sign in?", ru: "Как войти в кабинет?" }, a: { en: "Enter your work email on the sign-in page and type the 6-digit code from the email, or press Continue with Google. No password is needed. If nothing arrives in a minute, check Spam. An administrator activates new accounts.", ru: "Введите рабочий email на странице входа и 6-значный код из письма — или нажмите «Войти через Google». Пароль не нужен. Если письма нет через минуту — проверьте «Спам». Новый аккаунт активирует администратор." } },
  { q: { en: "Why don't I see some departments?", ru: "Почему я не вижу некоторые отделы?" }, a: { en: "Your role decides which sections you see. Ask the owner or an administrator to change your role or access in Users & roles.", ru: "Набор разделов зависит от роли. Попросите владельца или администратора изменить роль или доступ в «Пользователи и роли»." } },
  { q: { en: "Why can't I mark a deal as Won?", ru: "Почему сделка не переходит в Won?" }, a: { en: "Sanctions and end-user screening must be Cleared first. Set the screening field to Cleared after the check in Security → Restricted-party screening.", ru: "Сначала санкционная проверка и проверка конечного пользователя должны быть Cleared. Отметьте результат после проверки в «Безопасность» → «Санкционные проверки»." }, section: "sales.pipeline" },
  { q: { en: "Why can't a container move to Shipping?", ru: "Почему контейнер не переходит в Shipping?" }, a: { en: "The export and end-user check must be Cleared before shipping. Update the Export check field once Legal confirms.", ru: "До отгрузки экспортная проверка и проверка конечного пользователя должны быть Cleared. Обновите поле после подтверждения юристов." }, section: "operations.builds" },
  { q: { en: "What does Controlled mean?", ru: "Что значит «Контролируемые»?" }, a: { en: "The record contains technical data under US export control. Only users marked US person can see it; the database enforces this.", ru: "В записи технические данные под экспортным контролем США. Видят только пользователи с отметкой US person; это защищено на уровне базы данных." } },
  { q: { en: "How does a post or article get published?", ru: "Как публикуется пост или статья?" }, a: { en: "1) Create it in Social media, Press, Interviews or Video. 2) Click the AI button to write the draft and edit it. 3) Click “Compliance check”: it must pass, or legal sets “Cleared by legal”. 4) Send for approval: management approves by email in one click. 5) Publish, then paste the link and the reach. Dates appear in the Marketing calendar and on your phone.", ru: "1) Создайте запись в «Соцсетях», «СМИ», «Интервью» или «Видео». 2) Нажмите ИИ-кнопку, чтобы получить черновик, и отредактируйте его. 3) Нажмите «Проверить комплаенс»: проверка должна пройти, либо юрист ставит «Cleared by legal». 4) Отправьте на согласование: руководство согласует из письма одной кнопкой. 5) Опубликуйте, затем вставьте ссылку и охват. Даты видны в маркетинговом календаре и в телефоне." }, section: "marketing.social" },
  { q: { en: "How do I switch between light and dark theme?", ru: "Как переключить светлую и тёмную тему?" }, a: { en: "Press the sun/moon button at the top right (or Dark theme at the bottom of the page). The whole Workspace, including the side menu, switches. By default it follows your device setting.", ru: "Нажмите кнопку солнце/луна справа вверху (или «Тёмная тема» внизу страницы). Переключается весь Workspace, включая боковое меню. По умолчанию тема следует настройке вашего устройства." } },
  { q: { en: "Where do I find the AGRON and StarDome logos?", ru: "Где взять логотипы AGRON и StarDome?" }, a: { en: "Marketing → Brand center → Logos. Each logo has a preview, where to use it and a PNG download. The AGRON™ logo is the only company logo: keep the ™ mark; it looks best on dark backgrounds.", ru: "«Маркетинг» → «Бренд-центр» → «Логотипы». У каждого — превью, где использовать и скачивание PNG. Логотип AGRON™ — единственный логотип компании: знак ™ сохраняем; лучше всего смотрится на тёмном фоне." }, section: "marketing.brand" },
  { q: { en: "How does the department menu work?", ru: "Как работает меню департаментов?" }, a: { en: "Click a department under the orange Departments caption: it moves to the top of the menu and opens its sections, starting with Overview. Only one department is open at a time, so the menu stays short.", ru: "Нажмите на департамент под оранжевой подписью «Departments»: он поднимется в начало меню и откроет разделы, первым — «Обзор». Открыт только один департамент, поэтому меню остаётся коротким." } },
  { q: { en: "How do I plan social posts with AI?", ru: "Как спланировать посты с помощью ИИ?" }, a: { en: "Marketing → Overview → Plan 4 weeks of posts → Suggest posts. AI proposes 8 posts with dates, channels and topics, using upcoming events and publications. Tick the ones you want: they appear in Social media as Ideas and in the Marketing calendar.", ru: "«Маркетинг» → «Обзор» → «Спланировать посты на 4 недели» → «Предложить посты». ИИ предложит 8 постов с датами, каналами и темами с учётом ближайших событий и публикаций. Отметьте нужные: они появятся в «Соцсетях» как идеи и в маркетинговом календаре." }, section: "marketing.social" },
  { q: { en: "How do I connect our social accounts?", ru: "Как подключить наши соцсети?" }, a: { en: "Open Marketing → Channels & accounts, open the card of the platform and paste the profile link and the analytics page. Then the Open and Analytics buttons work from the Marketing overview. Statistics arrive by hand, by CSV import or, for YouTube, from the API. Passwords are never stored in Workspace: note only who has admin access.", ru: "Откройте «Маркетинг» → «Каналы и аккаунты», откройте карточку платформы и вставьте ссылку на профиль и страницу аналитики. После этого кнопки «Открыть» и «Аналитика» работают прямо из обзора маркетинга. Статистика вносится вручную, импортом CSV или, для YouTube, из API. Пароли в Workspace не хранятся: отмечайте только, у кого админ-доступ." }, section: "marketing.channels" },
  { q: { en: "How do I import statistics from LinkedIn, Meta, X or YouTube?", ru: "Как загрузить статистику из LinkedIn, Meta, X или YouTube?" }, a: { en: "In the platform, export analytics as CSV for the period (hover Import CSV on the card to see where). On the channel card press Import CSV and choose the file: Workspace finds the date and the known columns, adds them up by month and shows a preview; press Save. Existing months are updated, not duplicated.", ru: "В платформе выгрузите аналитику в CSV за период (наведите на «Импорт CSV» в карточке — подсказка покажет, где). В карточке канала нажмите «Импорт CSV» и выберите файл: Workspace найдёт дату и знакомые колонки, сложит их по месяцам и покажет предпросмотр; нажмите «Сохранить». Уже внесённые месяцы обновляются, а не дублируются." }, section: "marketing.metrics" },
  { q: { en: "How do I turn on automatic YouTube statistics?", ru: "Как включить автоматическую статистику YouTube?" }, a: { en: "Free: in Google Cloud Console create a project, enable YouTube Data API v3 and create an API key. The owner adds it in Vercel as YOUTUBE_API_KEY and redeploys. Put the channel ID (UC…) or @handle in the YouTube card; the Update from YouTube button then refreshes subscribers, views and videos.", ru: "Бесплатно: в Google Cloud Console создайте проект, включите YouTube Data API v3 и создайте ключ API. Владелец добавляет его в Vercel как YOUTUBE_API_KEY и перезапускает деплой. В карточке YouTube укажите ID канала (UC…) или @аккаунт; кнопка «Обновить из YouTube» обновит подписчиков, просмотры и число видео." }, section: "marketing.channels" },
  { q: { en: "How does the system check work?", ru: "Как работает проверка систем?" }, a: { en: "Technical → Overview → Check now. Our server opens the health link of each system (or its main link) over https, with a 7-second limit, and saves the result: Operational, Degraded (slow or error) or Down, with response time and time of check. Private and internal addresses are never opened.", ru: "«Технический» → «Обзор» → «Проверить сейчас». Наш сервер открывает адрес проверки каждой системы (или основную ссылку) по https с ограничением 7 секунд и сохраняет результат: работает, с проблемами (медленно или ошибка) или не работает, со временем ответа и временем проверки. Внутренние и частные адреса не открываются." }, section: "technical.systems" },
  { q: { en: "How do I make a marketing or technical report?", ru: "Как сделать маркетинговый или технический отчёт?" }, a: { en: "Open the department Overview and press Report. Choose the period, press AI summary for conclusions and next steps, then PDF, Print, Copy or Download. Numbers come only from Workspace statistics and records.", ru: "Откройте «Обзор» департамента и нажмите «Отчёт». Выберите период, нажмите «Выводы ИИ» для итогов и следующих шагов, затем PDF, «Печать», «Копировать» или «Скачать». Цифры берутся только из статистики и записей Workspace." } },
  { q: { en: "How do I check our domains for email spoofing and HTTPS problems?", ru: "Как проверить наши домены на подделку почты и проблемы HTTPS?" }, a: { en: "Security → Overview → Domain and website security → Scan. Green = fine, amber = improve, red = fix now. Typical fixes: add an SPF record, set DMARC to quarantine or reject, turn on DKIM in Google Admin, renew the certificate. Add risk creates a Cybersecurity record with the finding.", ru: "«Безопасность» → «Обзор» → «Безопасность доменов и сайтов» → «Проверить». Зелёный — в порядке, жёлтый — улучшить, красный — исправить сейчас. Типичные исправления: добавить запись SPF, перевести DMARC в quarantine или reject, включить DKIM в Google Admin, обновить сертификат. «В риски» создаёт запись в «Кибербезопасности»." }, section: "security.cyber" },
  { q: { en: "How do I screen a client, vessel or vendor?", ru: "Как проверить клиента, судно или поставщика?" }, a: { en: "Security → Restricted-party screening → New: party name, type, country (two letters, e.g. AE) and IMO for vessels. Press Screen now: the US Consolidated Screening List is searched (when CSL_API_KEY is set) and each possible match is shown. OFAC, EU, UN, Equasis and MarineTraffic open in one click. Put the result into the record, review it, then set Cleared, Flagged or Escalated.", ru: "«Безопасность» → «Санкционные проверки» → «Новая»: название стороны, тип, страна (две буквы, например AE) и IMO для судна. Нажмите «Проверить сейчас»: поиск идёт по сводному списку США (когда задан CSL_API_KEY), каждое возможное совпадение показывается. OFAC, ЕС, ООН, Equasis и MarineTraffic открываются одним нажатием. Вставьте результат в запись, проверьте и поставьте Cleared, Flagged или Escalated." }, section: "security.screening" },
  { q: { en: "How do I turn on automatic sanctions screening?", ru: "Как включить автоматическую санкционную проверку?" }, a: { en: "Free: register at developer.trade.gov, subscribe to the Consolidated Screening List API and copy the subscription key. The owner adds it in Vercel as CSL_API_KEY and redeploys. Without the key the official search sites still open from every screening record.", ru: "Бесплатно: зарегистрируйтесь на developer.trade.gov, подпишитесь на API Consolidated Screening List и скопируйте ключ. Владелец добавляет его в Vercel как CSL_API_KEY и перезапускает деплой. Без ключа официальные сайты поиска всё равно открываются из каждой записи проверки." }, section: "security.screening" },
  { q: { en: "How do I review who has access to Workspace?", ru: "Как проверить, у кого есть доступ к Workspace?" }, a: { en: "Owners and administrators: Security → Overview → Workspace access review → Load accounts. Check the notes (never signed in, inactive 60+ days, external, waiting for a role), change roles in Users & roles, then press Record the review. Do it every quarter.", ru: "Владельцы и администраторы: «Безопасность» → «Обзор» → «Проверка доступов к Workspace» → «Загрузить аккаунты». Посмотрите отметки (не входил, неактивен 60+ дней, внешний, ждёт роль), поправьте роли в «Пользователи и роли» и нажмите «Записать проверку». Делайте раз в квартал." }, section: "security.access" },
  { q: { en: "How do I track a shipment?", ru: "Как отследить груз?" }, a: { en: "In Operations → Logistics, fill in Carrier and the tracking, container or AWB number. A Track button appears in the record and opens the carrier's tracking page (Maersk, Hapag-Lloyd, DHL, FedEx, UPS, Aramex).", ru: "В «Операции» → «Логистика» укажите перевозчика и номер отслеживания, контейнера или AWB. В записи появится кнопка «Отследить», она откроет страницу перевозчика (Maersk, Hapag-Lloyd, DHL, FedEx, UPS, Aramex)." }, section: "operations.logistics" },
  { q: { en: "Where are exchange rates and the currency converter?", ru: "Где курсы валют и конвертер?" }, a: { en: "Finance → Overview → Exchange rates and converter. EUR and GBP come from the European Central Bank daily; AED is fixed at 3.6725 per USD. Type an amount and currency to see it in the others.", ru: "«Финансы» → «Обзор» → «Курсы валют и конвертер». EUR и GBP — ежедневно от Европейского центробанка; AED привязан к доллару: 3,6725 за USD. Введите сумму и валюту — увидите её в других валютах." }, section: "finance.metrics" },
  { q: { en: "Does Workspace make backups?", ru: "Делает ли Workspace резервные копии?" }, a: { en: "Yes. Every Monday all data is saved in a private store (last 8 copies). The free database plan has no backups of its own, so this matters. To also receive an encrypted copy by email, the owner adds a long backup password in Vercel as BACKUP_PASSPHRASE. Attached files stay in storage; a full local copy with files is made in Administration → System.", ru: "Да. Каждый понедельник все данные сохраняются в закрытое хранилище (последние 8 копий). У бесплатного тарифа базы своих копий нет, поэтому это важно. Чтобы ещё получать зашифрованную копию на почту, владелец добавляет длинный пароль копий в Vercel как BACKUP_PASSPHRASE. Вложенные файлы остаются в хранилище; полная локальная копия с файлами делается в «Администрирование» → «Система»." } },
  { q: { en: "How do I save a backup to my computer?", ru: "Как сохранить копию на свой компьютер?" }, a: { en: "Owner: Administration → System → Local copy → tick Include attached files, type a password if you want the file encrypted, press Download the copy. You get one file: AGRON_Workspace_backup_<date>.zip or .agronbackup (encrypted). Keep the password separately.", ru: "Владелец: «Администрирование» → «Система» → «Локальная копия» → отметьте «Включить вложенные файлы», введите пароль, если нужно шифрование, нажмите «Скачать копию». Получится один файл: AGRON_Workspace_backup_<дата>.zip или .agronbackup (зашифрованный). Пароль храните отдельно." } },
  { q: { en: "How do I restore deleted records from a backup?", ru: "Как восстановить удалённые записи из копии?" }, a: { en: "Owner: Administration → System → Open or restore a backup → choose the file (enter its password if encrypted). You see what is inside by department. Restore missing records adds back only records and comments that no longer exist; existing records are never changed.", ru: "Владелец: «Администрирование» → «Система» → «Открыть или восстановить копию» → выберите файл (введите пароль, если он зашифрован). Будет видно содержимое по департаментам. «Восстановить недостающие записи» вернёт только записи и комментарии, которых больше нет; существующие записи не меняются." } },
  { q: { en: "Who gets monitoring alerts and monthly reports?", ru: "Кто получает тревоги мониторинга и ежемесячные отчёты?" }, a: { en: "Monitoring runs every day at 10:00 UTC; owners, administrators and the security role get an email only when a system is down or slow, a certificate expires within 30 days or email protection breaks. On the 1st, owners, administrators and management get one email with every department's report for the past month, without export-controlled records.", ru: "Мониторинг идёт каждый день в 10:00 UTC; владельцы, администраторы и роль «Безопасность» получают письмо только когда система не отвечает или медленная, сертификат истекает в ближайшие 30 дней или ломается защита почты. 1-го числа владельцы, администраторы и руководство получают одно письмо с отчётами всех департаментов за прошлый месяц, без записей под экспортным контролем." } },
  { q: { en: "Who can see that someone opened controlled data?", ru: "Кто видит, что кто-то открывал контролируемые данные?" }, a: { en: "Every time a record marked US persons only, or one of its files, is opened, Workspace writes who, what and when. Owners, administrators, management and the security role see the log on Security → Overview. Keep it for audits of the technology control plan.", ru: "Каждый раз, когда открывают запись с пометкой «только US persons» или её файл, Workspace записывает кто, что и когда. Журнал видят владельцы, администраторы, руководство и роль «Безопасность» в «Безопасность» → «Обзор». Он нужен для проверок плана контроля технологий." }, section: "security.tcp" },
  { q: { en: "How do I link a build to its deal and see the whole chain?", ru: "Как связать сборку со сделкой и увидеть всю цепочку?" }, a: { en: "Open the build, in Deal (linked) type part of the deal name and pick it; do the same for Screening (linked). Save. The Linked records panel then shows the client, deal, screening, proposal, contract, invoices, shipments, installation, unit and support tickets connected to it.", ru: "Откройте сборку, в поле «Сделка (связь)» наберите часть названия сделки и выберите её; так же для «Санкционная проверка (связь)». Сохраните. В блоке «Связанные записи» появятся клиент, сделка, проверка, КП, договор, счета, отгрузки, монтаж, система и заявки сервиса." }, section: "operations.builds" },
  { q: { en: "How do I send a presentation to a client?", ru: "Как отправить клиенту презентацию?" }, a: { en: "Open Marketing → Presentations & sales kit, open the item and click Email. Or in any email click “Add files from Media library”. Links stay valid for 7 days.", ru: "Откройте «Маркетинг» → «Презентации и материалы», откройте материал и нажмите «Письмо». Или в любом письме — «Добавить файлы из Медиатеки». Ссылки действуют 7 дней." }, section: "marketing.media" },
  { q: { en: "How do I invite a partner or vendor?", ru: "Как пригласить партнёра или поставщика?" }, a: { en: "Administration → Users & roles → Invite: enter the email, role Partner or Vendor, and their company name. They will see only records shared with that company.", ru: "«Администрирование» → «Пользователи и роли» → «Пригласить»: email, роль «Партнёр» или «Поставщик» и название компании. Они увидят только записи, открытые этой компании." } },
  { q: { en: "How do I share a record with a partner?", ru: "Как открыть запись партнёру?" }, a: { en: "In the record set External visibility to the partner's company name, or * for all partners, vendors and investors.", ru: "В записи укажите в поле «Видимость для внешних» название компании партнёра или * — для всех партнёров, поставщиков и инвесторов." } },
  { q: { en: "Does the AI give legal advice?", ru: "Даёт ли ИИ юридические консультации?" }, a: { en: "No. Legal, export and tax answers are preliminary and marked so. Final decisions are made by counsel.", ru: "Нет. Юридические, экспортные и налоговые ответы предварительные и так помечены. Окончательное решение принимает юрист." } },
  { q: { en: "How is AI cost controlled?", ru: "Как контролируются расходы на ИИ?" }, a: { en: "One company API key, a monthly limit per user, Quick mode by default, cached instructions, and reuse of saved answers: repeated questions are answered from the FAQ for free.", ru: "Один ключ API компании, месячный лимит на пользователя, режим «Быстро» по умолчанию, кэширование инструкций и повторное использование ответов: повторные вопросы отвечаются из FAQ бесплатно." } },
  { q: { en: "Where are files stored and how big can they be?", ru: "Где хранятся файлы и какого размера?" }, a: { en: "In the company's private Supabase storage, up to 50 MB per file. Access follows the record: if you can't see the record, you can't open its files.", ru: "В закрытом хранилище Supabase компании, до 50 МБ на файл. Доступ как у записи: не видите запись — не откроете и файлы." } },
  { q: { en: "Can I store ITAR technical data here?", ru: "Можно ли хранить здесь ITAR-данные?" }, a: { en: "No. This workspace runs on commercial cloud. ITAR data needs a separate compliant environment agreed with export counsel.", ru: "Нет. Кабинет работает в коммерческом облаке. Для ITAR нужна отдельная среда, согласованная с экспортным юристом." } },
];
